INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10442, 407531, 'tt4998772', NULL, 'Bedeviled', 'Bedeviled', 'movie', 2017, 'https://image.tmdb.org/t/p/w500/nj41nDNmpRNQSaHithu8VmOGUDG.jpg', 'https://image.tmdb.org/t/p/original/gnaExMrBDw9hhgb1GacWapOV3mV.jpg', 'When a group of teenagers receive an invite to download the latest smartphone app, an intelligent personal assistant, they expect a harmless way to get directions and restaurant recommendations. But the sinister nature of the app soon reveals itself, tormenting the friends by tapping into their darkest fears.', NULL, NULL, 1.2681, 5.215, 0, 6.01, '2026-08-19 01:49:52', '2026-08-19 01:49:52');
