INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10446, 13633, 'tt0085210', NULL, 'Bad Boys', 'Bad Boys', 'movie', 1983, 'https://image.tmdb.org/t/p/w500/5nHZ3wflOifKJMUcTCw0isKhmCv.jpg', 'https://image.tmdb.org/t/p/original/yIpaahwOBk4uVUBNcHkoZdcXPCK.jpg', 'Mick O''Brien is a young Chicago street thug torn between a life of petty crime and the love of his girlfriend. But when the heist of a local drug dealer goes tragically wrong Mick is sentenced to a brutal juvenile prison where violence is a rite of passage and respect is measured in vengeance.', NULL, NULL, 5.298, 7.0, 0, 1.11, '2026-08-19 01:49:52', '2026-08-19 01:49:52');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10447, 29039, 'tt0069729', NULL, 'The Arena', 'The Arena', 'movie', 1974, 'https://image.tmdb.org/t/p/w500/rqQlMxVJWPwYM74IhEqDane2FSX.jpg', 'https://image.tmdb.org/t/p/original/jTbbgsAt0Vr8HHOQ2uE7VhFyBpZ.jpg', 'Female gladiators fight to the death. Inspired by the story of Spartacus, follow the adventures of a bevy of slave girls who, upon finding themselves thrust into the gladiator ring, mount a vicious rebellion to fight their way to freedom.', NULL, NULL, 3.166, 5.314, 0, 1.11, '2026-08-19 01:49:52', '2026-08-19 01:49:52');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10448, 8923, 'tt0385002', NULL, 'Green Street Hooligans', 'Green Street Hooligans', 'movie', 2005, 'https://image.tmdb.org/t/p/w500/oTxHFRSbFcCWdfJB4ozA41Yq57c.jpg', 'https://image.tmdb.org/t/p/original/isRzCN0ATsZ4CdBf6CSGA2ruclW.jpg', 'After being wrongfully expelled from Harvard University, American Matt Buckner flees to his sister''s home in England. Once there, he is befriended by her charming and dangerous brother-in-law, Pete Dunham, and introduced to the underworld of British football hooliganism. Matt learns to stand his ground through a friendship that develops against the backdrop of this secret and often violent world. ''Green Street Hooligans'' is a story of loyalty, trust and the sometimes brutal consequences of living close to the edge.', NULL, NULL, 5.2952, 7.275, 0, 5.56333333333333346e+00, '2026-08-19 01:49:52', '2026-08-19 01:49:52');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10449, 10296, 'tt0385705', NULL, 'The Football Factory', 'The Football Factory', 'movie', 2004, 'https://image.tmdb.org/t/p/w500/ja76eLRw7XSc1VdlNXEb8ufTIoW.jpg', 'https://image.tmdb.org/t/p/original/7WpbG7uASBBX6oT9TQMxl8mtfkx.jpg', 'The Football Factory is more than just a study of the English obsession with football violence, it''s about men looking for armies to join, wars to fight and places to belong. A forgotten culture of Anglo Saxon males fed up with being told they''re not good enough and using their fists as a drug they describe as being more potent than sex and drugs put together.', NULL, NULL, 2.1844, 6.402, 0, 5.5649999999999995e+00, '2026-08-19 01:49:52', '2026-08-19 01:49:52');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10450, 15070, 'tt0281322', NULL, 'Undisputed', 'Undisputed', 'movie', 2002, 'https://image.tmdb.org/t/p/w500/q8smM97IBBEWmkaUCmkPqysh7k7.jpg', 'https://image.tmdb.org/t/p/original/sTkJSkDkJnxCsk2FvKY2OL7NQcy.jpg', 'Monroe Hutchens is the heavyweight champion of Sweetwater, a maximum security prison. He was convicted to a life sentence due to a passionate crime. Iceman Chambers is the heavyweight champion, who lost his title due to a rape conviction to ten years in Sweetwater. When these two giants collide in the same prison, they fight against each other disputing who is the real champion.', NULL, NULL, 5.8477, 6.518, 0, 2.11, '2026-08-19 01:49:52', '2026-08-19 01:49:52');
