INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10461, 1456928, 'tt37271308', NULL, 'I Would Rather Kill You', '차라리 죽여', 'movie', 2025, 'https://image.tmdb.org/t/p/w500/v3z8uYRLVLiz9LXp62GoQ0AFPZR.jpg', 'https://image.tmdb.org/t/p/original/5NzHayF1hrTqpHNmqVfnN0mPxDi.jpg', 'After leaving behind the hectic city life, sisters Sun-young and Ji-young move to a secluded rural village. Sun-young, the older sister, is practical and responsible, while Ji-young is carefree and detached. Dae-geun, the passionate youth leader who works tirelessly for the happiness and prosperity of the village, and Bong-sam, the village chief, both fall head over heels for the sisters who bring a fiery energy to their once-quiet town. Other suspicious men begin to obsess over the sisters, including a wanted criminal who causes a stir in the village. One man after another, the village''s men fall into the wild trap of desire.', NULL, NULL, 14.9599, 6.8, 0, 8.02, '2026-08-19 01:49:52', '2026-08-19 01:49:52');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10462, 1597, 'tt0212338', NULL, 'Meet the Parents', 'Meet the Parents', 'movie', 2000, 'https://image.tmdb.org/t/p/w500/5tXJ9ctuyEOMUFLaeqRisbXowWs.jpg', 'https://image.tmdb.org/t/p/original/qcVrlyPFlPgCsmzorvELvpJN9Be.jpg', 'Greg Focker is ready to marry his girlfriend, Pam, but before he pops the question, he must win over her formidable father, humorless former CIA agent Jack Byrnes, at the wedding of Pam''s sister. As Greg bends over backward to make a good impression, his visit to the Byrnes home turns into a hilarious series of disasters, and everything that can go wrong does, all under Jack''s critical, hawklike gaze.', NULL, NULL, 10.4377, 6.7, 0, 8.01, '2026-08-19 01:49:52', '2026-08-19 01:49:52');
