INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10468, 178522, 'tt0266643', NULL, 'In Absentia', 'In Absentia', 'movie', 2000, 'https://image.tmdb.org/t/p/w500/uDHXwFNiojhO5CRN5EfkP5N9i43.jpg', 'https://image.tmdb.org/t/p/original/d8yQ2OFQn8z6BXjto3uNULVqOaD.jpg', 'A woman sits alone on a chair at a table in a room on one of the top floors of an asylum. Bright spot lights dot the night, sometimes shining on her window. She sharpens pencils and writes on a page in a copy book. The pencil point often breaks under her fingers'' force. She places broken points outside the window on the sill. A satanic figure is somewhere nearby, animated but of straw or clay, not flesh. She finishes her writing, tears the paper from the pad, folds it, places it in an envelope, and slips it through a slot. Is she writing to her husband? "Sweetheart, come."', NULL, NULL, 0.5813, 6.5, 0, 6.51, '2026-08-19 01:49:52', '2026-08-19 01:49:52');
