INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10505, 55785, 'tt1560970', NULL, 'Neds', 'Neds', 'movie', 2010, 'https://image.tmdb.org/t/p/w500/a964EBCChUHims8RxfU1LC0rws0.jpg', 'https://image.tmdb.org/t/p/original/mehTCxRizppNtixQR05ZIzz5Zjf.jpg', 'NEDs (Non Educated Delinquents) is the story of a young man’s journey from prize-winning schoolboy to knife-carrying teenager. Struggling against the low expectations of those around him, John McGill changes from victim to avenger, scholar to NED, altar boy to glue sniffer. When he attempts to change back again, his new reality and recent past make conformity near impossible and violent self determination near inevitable.', NULL, NULL, 1.282, 6.759, 0, 8.01, '2026-08-19 01:49:52', '2026-08-19 01:49:52');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10506, 264239, 'tt0094242', NULL, 'Reflections', 'Вeћ виђeно', 'movie', 1987, 'https://image.tmdb.org/t/p/w500/8k3Wf9soKQv8taEBVMexX3AnbMs.jpg', 'https://image.tmdb.org/t/p/original/8BmxtHpyh3X1TcXMWyMag4OQbTn.jpg', 'Mihajlo, an introvert piano teacher starts romance with a pretty careerist who teaches modeling at the university in Belgrade where they both work. His feelings are awakened after a long period, but this relationship makes him see the flashbacks, as well as yet unseen images that remind him of his troubled childhood - as if he experienced this already. When their university wins a contest to hold public TV performance, Mihailo fails to play the piano on the decisive night and she dumps him. The boiling point is about to come.', NULL, NULL, 0.7285, 6.352, 0, 10.02, '2026-08-19 01:49:52', '2026-08-19 01:49:52');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10507, 939914, 'tt12724306', NULL, 'Glorious', 'Glorious', 'movie', 2022, 'https://image.tmdb.org/t/p/w500/gttZLC3yhLFx1EnfjEUaDb2YAwl.jpg', 'https://image.tmdb.org/t/p/original/up8mHTvnn92bqcq3paWbFdWWXXz.jpg', 'After a breakup, Wes ends up at a remote rest stop. He finds himself locked inside the bathroom with a mysterious figure speaking from an adjacent stall. Soon Wes realizes he is involved in a situation more terrible than he could imagine.', NULL, NULL, 1.2871, 5.806, 0, 3.52, '2026-08-19 01:49:52', '2026-08-19 01:49:52');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10508, 1419169, NULL, NULL, 'The Alien Hand 3', 'The Alien Hand 3', 'movie', NULL, 'https://image.tmdb.org/t/p/w500/kDSuWwWLtMoh4xvlFH6sU6uNhR6.jpg', NULL, 'Saket, an ordinary individual, stumbles upon a powerful chain that grants him incredible superpowers. With these newfound abilities, Saket becomes the city''s protector, fighting crime and safeguarding its citizens. However, his life takes an unexpected turn when the chain is stolen by Jay, a ruthless villain who seeks to use its power to destroy the world and elevate himself to god-like status. In a race against time, Saket embarks on a mission to reclaim the chain and stop Jay''s destructive plans. Along the way, he encounters a mysterious and powerful superhero named Alien Hand, whose own motives and powers add complexity to their conflict. The movie centers around the intense face-off between Alien hand and Jay, with the fate of the world hanging in the balance.', NULL, NULL, 0.4235, 0.0, 0, 9.01, '2026-08-19 01:49:52', '2026-08-19 01:49:52');
