INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10557, 20608, 'tt0130184', NULL, 'Pervirella', 'Pervirella', 'movie', 1997, 'https://image.tmdb.org/t/p/w500/blclQGN6tsCN3gcwsl7Xxgtwlqm.jpg', 'https://image.tmdb.org/t/p/original/mGFq2RTTh3KdXVjKenzSqN9odCT.jpg', 'This is the story of the beautiful young Pervirella. Set in the mythical English land of Condon, the grotesque, power-mad Queen Victoria builds a wall around the country and establishes a "Monarchy of Terror." Intellectuals and "pervs" are prosecuted and killed, or driven underground to form the "Cult of Perv." Their leader, the Demon Nanny gives birth to a possible savior, then dies. The infant Pervirella grows to maturity with supernatural speed and shows amazing abilities, including raging nymphomania whenever her magical necklace is removed. Pervirella is sought by various rebels, agents of Victoria, the Cult of Perv, and a trio of witches. Eventually she teams up with Amicus Reilly, a James Bond spoof played to stiff, campy perfection by the late David Warbeck. Wild adventures ensue!', NULL, NULL, 0.6667, 4.125, 0, 1.04, '2026-08-19 01:49:52', '2026-08-19 01:49:52');
