INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10572, 55950, 'tt0108569', NULL, 'Wilder Napalm', 'Wilder Napalm', 'movie', 1993, 'https://image.tmdb.org/t/p/w500/9FHa9pxrt9eDBoW04TZx7l2kcoN.jpg', 'https://image.tmdb.org/t/p/original/cA1GcR7bcWCntr7s1BOdEBhjzTx.jpg', 'Wilder and Wallace are brothers and pyrokinetics. Ever since childhood they''ve been able to start fires with their minds but following a tragedy in which they accidentally killed a man, the brothers have grown up very differently. Wilder has become a regular 9-5 workaday joe but Wallace performs his feats with a traveling circus. When the circus comes to Wilder''s home town Wallace starts coming on strong to Wilder''s wife, Vida who, ironically, is a slight pyromaniac.', NULL, NULL, 1.2548, 5.6, 0, 10.02, '2026-08-19 01:49:52', '2026-08-19 01:49:52');
