INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10616, 94954, 'tt7216636', NULL, 'Hazbin Hotel', 'Hazbin Hotel', 'tv', 2024, 'https://image.tmdb.org/t/p/w500/aVYHMW8pdzJ9qG1OGRMKyGy9xor.jpg', 'https://image.tmdb.org/t/p/original/9K6QtLqyocVHgIZe4yqCIl1q2ZR.jpg', 'In attempt to find a non-violent alternative for reducing Hell''s overpopulation, the daughter of Lucifer opens a rehabilitation hotel that offers a group of misfit demons a chance at redemption.', NULL, NULL, 35.3704, 8.556, 0, 10.01, '2026-08-19 01:49:52', '2026-08-19 01:49:52');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10617, 60685, 'tt3079768', NULL, 'Dominion', 'Dominion', 'tv', 2014, 'https://image.tmdb.org/t/p/w500/2rBiS2m5hZbTSxorXQmUcbt2cTU.jpg', 'https://image.tmdb.org/t/p/original/3I66moIh8haxvauJtojLRW5lxjy.jpg', 'Based on characters from the hit theatrical film ‘Legion’ (2010), ‘Dominion’ is an epic supernatural drama set in the year 25 A.E. In this transformed post–apocalyptic future an army of lower angels, assembled by the archangel Gabriel, has waged a war of possession against mankind. The archangel Michael, turning against his own kind, has chosen to side with humanity against Gabriel. Rising out of the ashes of the 25-year-long battle are newly fortified cities which protect the human survivors. In Vega (formerly Las Vegas), the largest of these cities, two houses vie for control and the stage is set for political upheaval and a dangerous power shift. Meanwhile, a rebellious young soldier begins a perilous journey as the war between the human race and the fallen angels hellbent on their domination escalates.', NULL, NULL, 7.4286, 6.503, 0, 9.51, '2026-08-19 01:49:52', '2026-08-19 01:49:52');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10618, NULL, NULL, 120, 'Diablo III', 'Diablo III', 'game', 2012, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2l1u.jpg', NULL, 'Diablo III is the third installment in Blizzard''s franchise. The game, like its predecessors, is a dungeon crawler in which the player fights against hordes of enemies ranging from beasts and undead to actual demons. The game has four acts, two game modes (normal and hardcore) as well as four difficulty levels: Normal, Nightmare, Hell and Inferno. A new addition to Diablo III is the auction house, where items are exchanged for in-game gold or real money, also usable to purchase Blizzard merchandise. The game features a wide array of achievements earned upon meeting certain requirements.', 'https://www.igdb.com/games/diablo-iii', '["PlayStation 3", "PlayStation 4", "PC (Microsoft Windows)", "Mac", "Xbox 360", "Xbox One"]', NULL, NULL, 0, 10.01, '2026-08-19 01:49:52', '2026-08-19 01:49:52');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10619, 81358, 'tt7472896', NULL, 'Mr Inbetween', 'Mr Inbetween', 'tv', 2018, 'https://image.tmdb.org/t/p/w500/1FkONly4j7hxi6Pz5CmuhRN1Ops.jpg', 'https://image.tmdb.org/t/p/original/2INMEKxee4z0mVYpHCS4AdPxgOb.jpg', 'Ray Shoesmith is a father, ex-husband, boyfriend and best friend: tough roles to juggle in the modern age. Even harder when you’re a criminal for hire.', NULL, NULL, 13.9231, 8.282, 0, 1.01, '2026-08-19 01:49:52', '2026-08-19 01:49:52');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10620, 40555, 'tt0095186', NULL, 'Full Moon in Blue Water', 'Full Moon in Blue Water', 'movie', 1988, 'https://image.tmdb.org/t/p/w500/3QsmmSgBvfK83j6EDtJZjBcsC5h.jpg', 'https://image.tmdb.org/t/p/original/AixgApoZo6dd9fZ5MmdnByimtep.jpg', 'Floyd, the owner of a bar on the Texas coast, has been depressed for a year after his wife disappeared in a swimming accident. He lives with his senile father-in-law "The General" and is helped by Jimmy, a former asylum inmate, and the good-natured Louise. The bar is rapidly losing money and Charlie wants to buy it cheaply before it becomes publicly known that a nearby bridge is to be built. Louise offers her savings to go into partnership with Floyd, but Floyd decides to sell when he is forced to pay his back taxes.', NULL, NULL, 1.0203, 6.114, 0, 7.01, '2026-08-19 01:49:52', '2026-08-19 01:49:52');
