INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10641, 36758, 'tt0117364', NULL, 'The Portrait of a Lady', 'The Portrait of a Lady', 'movie', 1996, 'https://image.tmdb.org/t/p/w500/yoUuMtWTQXzfARYE0nF7Nn7gRuS.jpg', 'https://image.tmdb.org/t/p/original/8Dc6WVeJjJcl9muNJmuuoOgkiB7.jpg', 'Ms. Isabel Archer isn''t afraid to challenge societal norms. Impressed by her free spirit, her kindhearted cousin writes her into his fatally ill father''s will. Suddenly rich and independent, Isabelle ventures into the world, along the way befriending a cynical intellectual and romancing an art enthusiast. However, the advantage of her affluence is called into question when she realizes the extent to which her money colors her relationships.', NULL, NULL, 2.7845, 5.952, 0, 1.01, '2026-08-19 01:49:52', '2026-08-19 01:49:52');
