INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10646, 499, 'tt0055852', NULL, 'Cléo from 5 to 7', 'Cléo de 5 à 7', 'movie', 1962, 'https://image.tmdb.org/t/p/w500/oelBStY4xpguaplRv15P3Za7Xsr.jpg', 'https://image.tmdb.org/t/p/original/oyatchDPpS4I9jpIIezFJGrmXcR.jpg', 'Agnès Varda eloquently captures Paris in the sixties with this real-time portrait of a singer set adrift in the city as she awaits test results of a biopsy. A chronicle of the minutes of one woman’s life, Cléo from 5 to 7 is a spirited mix of vivid vérité and melodrama, featuring a score by Michel Legrand and cameos by Jean-Luc Godard and Anna Karina.', NULL, NULL, 3.8301, 7.659, 0, 2.01, '2026-08-19 01:49:52', '2026-08-19 01:49:52');
