INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10648, 35114, 'tt0377770', NULL, 'Destino', 'Destino', 'movie', 2003, 'https://image.tmdb.org/t/p/w500/7IyDJdaGlU7olLC08mSwLJTmsC3.jpg', 'https://image.tmdb.org/t/p/original/hsx40OreCcM84gNmOeVssUvetRg.jpg', 'Short film to a song of love lost and rediscovered, a woman sees and undergoes surreal transformations. Her lover''s face melts off, she dons a dress from the shadow of a bell and becomes a dandelion, ants crawl out of a hand and become Frenchmen riding bicycles. Not to mention the turtles with faces on their backs that collide to form a ballerina, or the bizarre baseball game.', NULL, NULL, 0.9122, 7.2, 0, 9.51, '2026-08-19 01:49:52', '2026-08-19 01:49:52');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10649, 13411, 'tt0328099', NULL, 'Malibu''s Most Wanted', 'Malibu''s Most Wanted', 'movie', 2003, 'https://image.tmdb.org/t/p/w500/bjYuoz2S8S1AED5QIMvmAi21drc.jpg', 'https://image.tmdb.org/t/p/original/bwkrnryQYBaYNagZoEuuPlOI2UM.jpg', 'A senator arranges for his son, a rich white kid who fancies himself black, to be kidnapped by a couple of black actors pretending to be murderers to try and shock him out of his plans to become a rapper.', NULL, NULL, 2.6958, 5.387, 0, 8.01, '2026-08-19 01:49:52', '2026-08-19 01:49:52');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10650, 749170, 'tt13357520', NULL, 'Heads of State', 'Heads of State', 'movie', 2025, 'https://image.tmdb.org/t/p/w500/lVgE5oLzf7ABmzyASEVcjYyHI41.jpg', 'https://image.tmdb.org/t/p/original/vJbEUMeI2AxBUZKjP6ZVeVNNTLh.jpg', 'The UK Prime Minister and US President have a public rivalry that risks their countries'' alliance. But when they become targets of a powerful enemy, they''re forced to rely on each other as they go on a wild, multinational run. Allied with Noel, a brilliant MI6 agent, they must find a way to thwart a conspiracy that threatens the free world.', NULL, NULL, 18.0485, 6.806, 0, 8.01, '2026-08-19 01:49:52', '2026-08-19 01:49:52');
