INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10652, 65891, 'tt0065669', NULL, 'The Dunwich Horror', 'The Dunwich Horror', 'movie', 1970, 'https://image.tmdb.org/t/p/w500/veoJRMZSk9RwTnDJmhhNj6WpJWx.jpg', 'https://image.tmdb.org/t/p/original/drYtJvtJXtdJtX0QCoOleG4Kine.jpg', 'Dr. Henry Armitage, an expert in the occult, goes to the old Whateley manor in Dunwich looking for Nancy Wagner, a student who went missing the previous night. He is turned away by Wilbur, the family''s insidious heir, who has plans for the young girl. But Armitage won''t be deterred. Through conversations with the locals, he soon unearths the Whateleys'' darkest secret — as well as a great evil.', NULL, NULL, 2.1783, 5.4, 0, 1.01, '2026-08-19 01:49:52', '2026-08-19 01:49:52');
