INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10654, NULL, NULL, 9176, 'Call of Cthulhu', 'Call of Cthulhu', 'game', 2018, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2d3a.jpg', NULL, 'Developed by seasoned studio Cyanide, Call of Cthulhu is an RPG-Investigation game with psychological horror and stealth mechanics, set in a deeply immersive world. On a mission to find the truth behind the death of an acclaimed artist and her family on a backwater island, the player will soon uncover a more disturbing truth as the Great Dreamer, Cthulhu, prepares its awakening...', 'https://www.igdb.com/games/call-of-cthulhu', '["PlayStation 4", "PC (Microsoft Windows)", "Xbox One", "Nintendo Switch"]', NULL, NULL, 0, 1.01, '2026-08-19 01:49:52', '2026-08-19 01:49:52');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10655, 13539, 'tt0195778', NULL, 'Here on Earth', 'Here on Earth', 'movie', 2000, 'https://image.tmdb.org/t/p/w500/shvubL3pIrCyEK22ZHrx00oNtCY.jpg', 'https://image.tmdb.org/t/p/original/qUkkAGbccOW5e0bWIjY85kK7Cud.jpg', 'Three lives of three young people intersect over the course of one summer. A rich student and a young working-class man accidentally destroy a diner when their impromptu road race takes a disastrous turn. Ordered by a judge to spend the summer repairing the building, they find themselves becoming rivals for the affections of the owner''s daughter.', NULL, NULL, 1.6488, 5.9, 0, 1.01, '2026-08-19 01:49:52', '2026-08-19 01:49:52');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10656, 134018, 'tt0844474', NULL, 'House of the Sleeping Beauties', 'Das Haus der schlafenden Schönen', 'movie', 2006, 'https://image.tmdb.org/t/p/w500/myzmLGcvh442NhvSauKZxNdOdV5.jpg', 'https://image.tmdb.org/t/p/original/mMxXy6BLvYlIlS0DgYl8kor0Gb0.jpg', 'Edmond, a man in his sixties whose wife has recently passed away, is told about a secret establishment where men can spend an entire night in bed alongside beautiful, sleeping young women, who stretch, roll over and dream, but never awaken. Bedazzled by their seductive yet innocent tenderness, but distressed about the reason for their deep sleep, he delves into the mystery of the house of sleeping beauties.', NULL, NULL, 0.73, 5.3, 0, 1.01, '2026-08-19 01:49:52', '2026-08-19 01:49:52');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10657, 14801, 'tt0064177', NULL, 'Colossus: The Forbin Project', 'Colossus: The Forbin Project', 'movie', 1970, 'https://image.tmdb.org/t/p/w500/kmVDlTzERxSvBrqtQurjKf1zEy1.jpg', 'https://image.tmdb.org/t/p/original/3eV9l3HhOGOytCilHJOACDL9DIT.jpg', 'The U.S. has handed over control of its nuclear defense system to the Colossus supercomputer designed by scientist Dr. Charles Forbin. It soon becomes clear, that the now-sentient Colossus is far more intelligent than its creator realized—with the fate of the world hanging in the balance.', NULL, NULL, 2.9505, 6.966, 0, 1.02, '2026-08-19 01:49:52', '2026-08-19 01:49:52');
