INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10664, 34708, 'tt0473578', NULL, 'Genshiken', 'げんしけん', 'tv', 2004, 'https://image.tmdb.org/t/p/w500/erC2U9IB0eIJpecKE6QxuK9Rkab.jpg', 'https://image.tmdb.org/t/p/original/h9IQsx7dMMJPDPRIKS44utEQOfP.jpg', 'Sasahara Kanji is a college freshman who decides to join a student society to share his hidden thoughts on manga, anime and gaming. As he participates in club activities such as visiting dojin shops and anime festivals he opens his mind and resolves that he will make his way into the otaku world.', NULL, NULL, 8.8862, 7.1, 0, 1.01, '2026-08-19 01:49:52', '2026-08-19 01:49:52');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10665, 315465, 'tt4272866', NULL, 'The Boy and the Beast', 'バケモノの子', 'movie', 2015, 'https://image.tmdb.org/t/p/w500/kRofx67xkbnJ6pAVcHdeMyBm4OM.jpg', 'https://image.tmdb.org/t/p/original/5qNBH6tY6Jihzo9SqzvrJFHMPgz.jpg', 'Kyuta, a boy living in Shibuya, and Kumatetsu, a lonesome beast from Jutengai, an imaginary world. One day, Kyuta forays into the imaginary world and, as he''s looking for his way back, meets Kumatetsu who becomes his spirit guide. That encounter leads them to many adventures.', NULL, NULL, 4.2656, 7.907, 0, 1.01, '2026-08-19 01:49:52', '2026-08-19 01:49:52');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10666, 2073, 'tt0197148', NULL, 'Mission Hill', 'Mission Hill', 'tv', 1999, 'https://image.tmdb.org/t/p/w500/hJV2F5jR8clYnQ2jgV0eU90HbiE.jpg', 'https://image.tmdb.org/t/p/original/gkumTWD2gMTRr3JjU604QKz0tdt.jpg', 'Meet overqualified, underemployed, 24-year-old Andy French. Ambition: to be a cartoonist. Occupation: salesman at Waterbed World. Hobby: Where''s the party? But responsibility soon knocks on the door of the loft apartment Andy shares with two fellow slackers when Kevin, a nerdy 17 -year-old who wears his SAT score on his shirt and his admiration for big brother Andy on his sleeve, moves in. And, for good measure, so does the French family''s dog. Friends, roomies, canines, countrymen: lend me your beers. They''re all part of the daze of Andy''s life.', NULL, NULL, 5.1608, 7.5, 0, 1.01, '2026-08-19 01:49:52', '2026-08-19 01:49:52');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10667, 47774, 'tt0291559', NULL, 'DJ Q.bert''s Wave Twisters', 'DJ Q.bert''s Wave Twisters', 'movie', 2001, 'https://image.tmdb.org/t/p/w500/9iLjS8o9O0stRIHwfYlqONVwMnv.jpg', NULL, 'A crew of heroes is determined to save the lost arts of Hip Hop. Break Dancing, Graffiti, MCing, and DJing from total extinction. The lost arts are being oppressed throughout inner-space by lord Ook and his evil minions the Chinheads. The dental commander Dr. Julio Azul DDS, assumed to be secretary Honey Drips, Dental Hygienist/Robot Rubbish, and Grandpa have a series of adventures, synch''d to the music. Armed with the ancient relic known as the Wave Twister (a small turntable/wristwatch, the only weapon powerful enough to defeat the enemies), they travel to the far ends of inner-space for a final confrontation with the sinister army of oppressors.', NULL, NULL, 0.4311, 6.955, 0, 1.01, '2026-08-19 01:49:52', '2026-08-19 01:49:52');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10668, 205281, 'tt8881732', NULL, 'Subway Surfers: The Animated Series', 'Subway Surfers: The Animated Series', 'tv', 2018, 'https://image.tmdb.org/t/p/w500/pvCoF2zFotVoKGYPh6tLe1EE7EQ.jpg', 'https://image.tmdb.org/t/p/original/hbd3nIrw1i8Qpiu1fvqS09auz5C.jpg', 'These misfit teens have skating adventures in their small town and sometimes get stopped by the cops, but the landing of certain alien technology changes these kids'' lives.', NULL, NULL, 1.8144, 6.4, 0, 1.01, '2026-08-19 01:49:52', '2026-08-19 01:49:52');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10669, 35837, 'tt1235827', NULL, 'Boogie', 'Boogie, el Aceitoso', 'movie', 2009, 'https://image.tmdb.org/t/p/w500/7AkYQbzcr2q0ls8YKGaKSJktUrX.jpg', 'https://image.tmdb.org/t/p/original/rNlT8SCVyDJinTQdMR2QU7eGaFb.jpg', 'Hoping to make some money, Boogie, a violent and ruthless assassin, kidnaps a witness a mafia boss wants dead.', NULL, NULL, 0.8666, 6.923, 0, 1.01, '2026-08-19 01:49:52', '2026-08-19 01:49:52');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10670, 129465, 'tt1313120', NULL, 'Hells', 'HELLS ANGELS', 'movie', 2008, 'https://image.tmdb.org/t/p/w500/wzakuhm5mMxZXt6oP6CbkJuA7rV.jpg', 'https://image.tmdb.org/t/p/original/1WCuIbszx4XNvaUrZIoBczC4MPp.jpg', 'Amagane Rinne has a fatal accident while hurrying to her first day of school. She suddenly arrives at an awkward school... in Hell, filled with demons. While she struggles and wishes to go back to the world from whence she came, Rinne befriends her demon schoolmates and develops an uncommon bond.', NULL, NULL, 2.3575, 6.865, 0, 1.01, '2026-08-19 01:49:52', '2026-08-19 01:49:52');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10671, 33641, 'tt0384833', NULL, 'Frankenfish', 'Frankenfish', 'movie', 2004, 'https://image.tmdb.org/t/p/w500/wEDsyEsd0mf5UJ8hxpD1UFCu06X.jpg', 'https://image.tmdb.org/t/p/original/3uJhw4tMRodXlZHk2aoRJ9L9qoT.jpg', 'When the body of a man is found completely destroyed in the swamps in Louisiana, the medical investigator Sam Rivers is assigned to investigate the murder. He travels with the biologist Mary Callahan to the location where the victim lived in a floating house and he meets his family and friends. They find that Chinese snake-heads genetically engineered that belong to a wealthy hunter are attacking and killing the locals. While the group fights to survive, the hunter Jeff arrives with his team to hunt the predators.', NULL, NULL, 1.9899, 5.607, 0, 2.01, '2026-08-19 01:49:52', '2026-08-19 01:49:52');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10672, 11892, 'tt0264935', NULL, 'Murder by Numbers', 'Murder by Numbers', 'movie', 2002, 'https://image.tmdb.org/t/p/w500/plH3TujSUVttiIikToKfwdCorJI.jpg', 'https://image.tmdb.org/t/p/original/5fsyOL5sNA4jpqgl9WsxHgbgTja.jpg', 'Tenacious homicide detective Cassie Mayweather and her still-green partner are working a murder case, attempting to profile two malevolently brilliant young men: cold, calculating killers whose dark secrets might explain their crimes.', NULL, NULL, 4.7006, 6.167, 0, 1.01, '2026-08-19 01:49:52', '2026-08-19 01:49:52');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10673, 20722, 'tt1361566', NULL, 'La Maison en Petits Cubes', 'つみきのいえ', 'movie', 2008, 'https://image.tmdb.org/t/p/w500/kNGiHnbAToF1iIkN2kOTCEEXtAc.jpg', 'https://image.tmdb.org/t/p/original/1EfLDlkrcgSUgxVT56T9PGUGs5N.jpg', 'La Maison en Petits Cubes tells the story of a grandfather''s memories as he adds more blocks to his house to stem the flooding waters.', NULL, NULL, 1.2413, 7.904, 0, 1.01, '2026-08-19 01:49:52', '2026-08-19 01:49:52');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10674, 48414, 'tt1502396', NULL, 'To the Sea', 'Alamar', 'movie', 2010, 'https://image.tmdb.org/t/p/w500/kakeJZOFUONyDFTLaSxfFJuAib1.jpg', 'https://image.tmdb.org/t/p/original/yg4DNTCX1Z8onZxNOAyX95gJB5c.jpg', 'Before leaving for Rome with his mother, five year old Natan  is taken by his father, Jorge, on an epic journey to the pristine Chinchorro reef off the coast of Mexico. As they fish, swim, and sail the turquoise waters of the open sea, Natan discovers the beauty of his Mayan heritage and learns to live in harmony with life above and below the surface, as the bond between father and son grows stronger before their inevitable farewell.', NULL, NULL, 1.476, 6.779, 0, 1.01, '2026-08-19 01:49:52', '2026-08-19 01:49:52');
