INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10676, 1377, 'tt0051745', NULL, 'Houseboat', 'Houseboat', 'movie', 1958, 'https://image.tmdb.org/t/p/w500/nfaOBiZktPHOV0f3DTqTftgTo3B.jpg', 'https://image.tmdb.org/t/p/original/gm6olhE6677l4ZfuhV9I1ntvkng.jpg', 'An Italian socialite on the run signs on as housekeeper for a widower with three children.', NULL, NULL, 2.2916, 6.4, 0, 1.01, '2026-08-19 01:49:52', '2026-08-19 01:49:52');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10677, 703745, 'tt11946300', NULL, 'Deep Blue Sea 3', 'Deep Blue Sea 3', 'movie', 2020, 'https://image.tmdb.org/t/p/w500/bKthjUmxjHjvJK8FktFfQdmwP12.jpg', 'https://image.tmdb.org/t/p/original/hIHtyIYgBqHybOgUdoAmveipuiO.jpg', 'Dr. Emma Collins and her team are spending their third summer on the island of Little Happy studying the effect of climate change on the great white sharks who come to the nearby nursery every year to give birth. Along with the last two inhabitants of this former fishing village, their peaceful life is disrupted when a "scientific" team led by her ex-boyfriend and marine biologist Richard show up looking for three bull sharks who we soon learn aren''t just any bull sharks.', NULL, NULL, 3.7539, 5.579, 0, 1.01, '2026-08-19 01:49:52', '2026-08-19 01:49:52');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10678, 347035, 'tt1227183', NULL, 'Swallows and Amazons', 'Swallows and Amazons', 'movie', 2016, 'https://image.tmdb.org/t/p/w500/y5ZVbjos0CqhKLMV77YzX6r12Ls.jpg', 'https://image.tmdb.org/t/p/original/5kCwzf43iPs1fr0H31MrOQBA8Xz.jpg', 'Four children dream of escaping the tedium of a summer holiday with their mother. When finally given permission to camp on their own on an island in the middle of a vast lake, they are overjoyed. But when they get there they discover they may not be alone… The battle for ownership of a lonely island teaches them the skills of survival, the value of friendship and the importance of holding your nerve.', NULL, NULL, 1.393, 6.354, 0, 1.01, '2026-08-19 01:49:52', '2026-08-19 01:49:52');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10679, 30877, 'tt0089338', NULL, 'Cut and Run', 'Inferno in diretta', 'movie', 1985, 'https://image.tmdb.org/t/p/w500/nM79J0phqXnnXxR2rYBIk880gRv.jpg', 'https://image.tmdb.org/t/p/original/aS46Kr6DCqUAKdLW0k1mOO8xmle.jpg', 'A reporter and her cameraman connect a surviving Jonestown leader and a TV exec''s missing son to a drug war where jungle installations are being massacred by an army of natives and a skilled white assassin.', NULL, NULL, 1.5036, 5.31, 0, 1.01, '2026-08-19 01:49:52', '2026-08-19 01:49:52');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10680, 833408, 'tt13830148', NULL, 'The Tale of King Crab', 'Re Granchio', 'movie', 2021, 'https://image.tmdb.org/t/p/w500/92TK8iqJCRe6kLAF7zmRVXyQ5JI.jpg', 'https://image.tmdb.org/t/p/original/kOy5RhoaAJt64L5naI4Oxfpbib0.jpg', 'Small town in Italy, end of the 19th century. Luciano, a drunk, doesn''t fit in the town. Rebelion against authority and a forbidden love makes him to commit a crime accidentally. To pay for his crime, he is forced into exile on the most remote island in the world, Argentina’s Tierra del Fuego. The hunt for the shipwreck treasure hidden on the island becomes his opportunity for redemption.', NULL, NULL, 0.6281, 7.109, 0, 10.01, '2026-08-19 01:49:52', '2026-08-19 01:49:52');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10681, 10684, 'tt0218791', NULL, 'Sherlock Holmes in the 22nd Century', 'Sherlock Holmes in the 22nd Century', 'tv', 1999, 'https://image.tmdb.org/t/p/w500/mwLwPQBOeS1ukxUMTh7Sq1aNM63.jpg', 'https://image.tmdb.org/t/p/original/28uPSHLwxNmpbNnBSs6Ry41X73R.jpg', 'Sherlock Holmes fights crime in the 22nd Century with help from his loyal friend, Dr. Watson, who is programmed into the brain of an android.', NULL, NULL, 4.5012, 7.941, 0, 1.01, '2026-08-19 01:49:52', '2026-08-19 01:49:52');
