INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10683, 124088, 'tt0104575', NULL, 'Just Another Girl on the I.R.T.', 'Just Another Girl on the I.R.T.', 'movie', 1993, 'https://image.tmdb.org/t/p/w500/jjBthOisXwuyUqBd1BAmIzdSf4S.jpg', 'https://image.tmdb.org/t/p/original/ogw4HLfdmSqjpZx6k0C4u5l3sFE.jpg', 'Chantel Mitchell, a hip, articulate, black high-school girl in Brooklyn, is determined not to become "just another girl on the IRT" (the IRT is one of NYC''s subway lines). She dreams of medical school, a family, and an escape from the generational poverty and street-corner life her friends seem to have accepted as their lot. But personal and sexual challenges confront Chantel on her way to fulfilling these dreams.', NULL, NULL, 0.6792, 6.9, 0, 1.01, '2026-08-19 01:49:52', '2026-08-19 01:49:52');
