INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10685, 9042, 'tt0402901', NULL, 'The Cave', 'The Cave', 'movie', 2005, 'https://image.tmdb.org/t/p/w500/gMfJo22XulGLA8h8yAjiLhdQusv.jpg', 'https://image.tmdb.org/t/p/original/hHhZBHknSjrtSnIEVqQtAjMBNu9.jpg', 'After a group of biologists discovers a huge network of unexplored caves in Romania and, believing it to be an undisturbed eco-system that has produced a new species, they hire the best American team of underwater cave explorers in the world. While exploring deeper into the underwater caves, a rockslide blocks their exit, and they soon discover a larger carnivorous creature has added them to its food chain.', NULL, NULL, 5.4535, 5.439, 0, 11.01, '2026-08-19 01:49:52', '2026-08-19 01:49:52');
