UPDATE "recommendations" SET "tmdb_id"=49049, "imdb_id"='tt1343727', "igdb_id"=NULL, "title"='Dredd', "original_title"='Dredd', "media_type"='movie', "release_year"=2012, "poster_url"='https://image.tmdb.org/t/p/w500/wLx65gtGVnUFCxceHWGszcruCZj.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/jUqDBi02CDjqrroC3Zl8hroBbSr.jpg', "overview"='In the future, America is a dystopian wasteland. The latest scourge is Ma-Ma, a prostitute-turned-drug pusher with a dangerous new drug and aims to take over the city. The only possibility of stopping her is an elite group of urban police called Judges, who combine the duties of judge, jury and executioner to deliver a brutal brand of swift justice. But even the top-ranking Judge, Dredd, discovers that taking down Ma-Ma isn’t as easy as it seems in this explosive adaptation of the hugely popular comic series.', "external_url"=NULL, "platforms"=NULL, "popularity"=9.2399, "vote_average"=6.859, "is_ambiguous"=0, "evidence_score"=5.95280357142857141e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-19 01:49:52' WHERE "id"=534;
