UPDATE "recommendations" SET "tmdb_id"=832, "imdb_id"='tt0022100', "igdb_id"=NULL, "title"='M', "original_title"='M - Eine Stadt sucht einen Mörder', "media_type"='movie', "release_year"=1931, "poster_url"='https://image.tmdb.org/t/p/w500/bTdZk3q2DWpBRnLiaaItKFWOVhI.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/5Pk1rGAtyblh9Xaq72T7ARCQSDQ.jpg', "overview"='In this classic German thriller, Hans Beckert, a serial killer who preys on children, becomes the focus of a massive Berlin police manhunt. Beckert''s heinous crimes are so repellant and disruptive to city life that he is even targeted by others in the seedy underworld network. With both cops and criminals in pursuit, the murderer soon realizes that people are on his trail, sending him into a tense, panicked attempt to escape justice.', "external_url"=NULL, "platforms"=NULL, "popularity"=4.1423, "vote_average"=8.061, "is_ambiguous"=0, "evidence_score"=7.68833333333333257e+00, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-19 01:49:52' WHERE "id"=1121;
