UPDATE "recommendations" SET "tmdb_id"=31414, "imdb_id"='tt0111341', "igdb_id"=NULL, "title"='Satantango', "original_title"='Sátántangó', "media_type"='movie', "release_year"=1994, "poster_url"='https://image.tmdb.org/t/p/w500/y38z0v4HJ12MHiKddLEoFlvPiBt.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/5a4Gmk2HNeefI4Rmwdmbyoy79oy.jpg', "overview"='Inhabitants of a small village in Hungary deal with the effects of the fall of Communism. The town''s source of revenue, a factory, has closed, and the locals, who include a doctor and three couples, await a cash payment offered in the wake of the shuttering. Irimias, a villager thought to be dead, returns and, unbeknownst to the locals, is a police informant. In a scheme, he persuades the villagers to form a commune with him.', "external_url"=NULL, "platforms"=NULL, "popularity"=4.9537, "vote_average"=8.037, "is_ambiguous"=0, "evidence_score"=16.0225, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-19 01:49:52' WHERE "id"=1132;
UPDATE "recommendations" SET "tmdb_id"=187, "imdb_id"='tt0401792', "igdb_id"=NULL, "title"='Sin City', "original_title"='Sin City', "media_type"='movie', "release_year"=2005, "poster_url"='https://image.tmdb.org/t/p/w500/i66G50wATMmPrvpP95f0XP6ZdVS.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/t9kQnqiaxQ8TLB25rTzDKLd0fdM.jpg', "overview"='Welcome to Sin City. This town beckons to the tough, the corrupt, the brokenhearted. Some call it dark… Hard-boiled. Then there are those who call it home — Crooked cops, sexy dames, desperate vigilantes. Some are seeking revenge, others lust after redemption, and then there are those hoping for a little of both. A universe of unlikely and reluctant heroes still trying to do the right thing in a city that refuses to care.', "external_url"=NULL, "platforms"=NULL, "popularity"=12.0682, "vote_average"=7.465, "is_ambiguous"=0, "evidence_score"=4.09559459459459418e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-19 01:49:52' WHERE "id"=1134;
