UPDATE "recommendations" SET "tmdb_id"=14756, "imdb_id"='tt1220719', "igdb_id"=NULL, "title"='Ip Man', "original_title"='葉問', "media_type"='movie', "release_year"=2008, "poster_url"='https://image.tmdb.org/t/p/w500/9bUIrDKnesNbBL1nAl1nt7gtocE.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/69QJSMkm5Hh0x9fLElZ8hjv5N4P.jpg', "overview"='A semi-biographical account of Yip Man, the first martial arts master to teach the Chinese martial art of Wing Chun. The film focuses on events surrounding Ip that took place in the city of Foshan between the 1930s to 1940s during the Second Sino-Japanese War. Directed by Wilson Yip, the film stars Donnie Yen in the lead role, and features fight choreography by Sammo Hung.', "external_url"=NULL, "platforms"=NULL, "popularity"=4.608, "vote_average"=7.764, "is_ambiguous"=0, "evidence_score"=2.07, "created_at"='2026-07-29 20:51:09', "updated_at"='2026-08-19 01:49:52' WHERE "id"=5137;
