UPDATE "recommendations" SET "tmdb_id"=8989, "imdb_id"='tt0093148', "igdb_id"=NULL, "title"='Harry and the Hendersons', "original_title"='Harry and the Hendersons', "media_type"='movie', "release_year"=1987, "poster_url"='https://image.tmdb.org/t/p/w500/5ZNWhOEsuNHIQ1gbtwdTGK7srCr.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/4DGZNuxMMcCjVjmn2INTUu66mWX.jpg', "overview"='Returning from a hunting trip in the forest, the Henderson family''s car hits an animal in the road. At first they fear it was a man, but when they examine the "body" they find it''s a "bigfoot". They think it''s dead so they decide to take it home (there could be some money in this). As you guessed, it isn''t dead. Far from being the ferocious monster they fear "Harry" to be, he''s a friendly giant.', "external_url"=NULL, "platforms"=NULL, "popularity"=9.4737, "vote_average"=6.13, "is_ambiguous"=0, "evidence_score"=1.05183333333333344e+01, "created_at"='2026-07-29 20:51:09', "updated_at"='2026-08-19 01:49:52' WHERE "id"=5143;
