UPDATE "recommendations" SET "tmdb_id"=25641, "imdb_id"='tt0206963', "igdb_id"=NULL, "title"='My First Mister', "original_title"='My First Mister', "media_type"='movie', "release_year"=2001, "poster_url"='https://image.tmdb.org/t/p/w500/xP2JKtdq77aWWZ1LCGsR68co5Jw.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/705d13uxddi59nqHbndanqkAbNQ.jpg', "overview"='Leelee Sobieski is brash, abrasive and vulnerable as a teenage child of divorce who hides her pain behind a mask of hard-edged gothic rebellion. Albert Brooks plays a man who is her total opposite, a precise and well-ordered menswear store owner of forty-nine who manages limited expectations and protects lonely secrets with pleasant ritual and quiet, ironic reserve. These two total opposites collide in conflict then come together in a surprising alliance, changing each other''s lives forever.', "external_url"=NULL, "platforms"=NULL, "popularity"=1.1698, "vote_average"=6.529, "is_ambiguous"=0, "evidence_score"=5.34333333333333282e+00, "created_at"='2026-07-29 20:51:09', "updated_at"='2026-08-19 01:49:52' WHERE "id"=5149;
