UPDATE "recommendations" SET "tmdb_id"=2587, "imdb_id"='tt0069824', "igdb_id"=NULL, "title"='Brother Sun, Sister Moon', "original_title"='Fratello sole, sorella luna', "media_type"='movie', "release_year"=1972, "poster_url"='https://image.tmdb.org/t/p/w500/hbe9jnRQKyxtLr2krJR6RBRwzae.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/s3h57HUNewjGiX2kCXaTzg5DAXr.jpg', "overview"='In his delirium from his return from war, Francesco Bernardone goes back in his memories to the days when he lived for parties and carnal pleasures. He slowly recovers, but after the illness he is no longer the Francesco that everybody knew. Instead of spending hours in taverns, he meditates on the beauty of God''s creatures, soon renouncing his riches and his family with plans to rebuild an abandoned church and his life.', "external_url"=NULL, "platforms"=NULL, "popularity"=2.018, "vote_average"=7.043, "is_ambiguous"=0, "evidence_score"=5.6425, "created_at"='2026-08-03 14:31:56', "updated_at"='2026-08-19 01:49:52' WHERE "id"=6638;
