UPDATE "recommendations" SET "tmdb_id"=8456, "imdb_id"='tt1023111', "igdb_id"=NULL, "title"='Never Back Down', "original_title"='Never Back Down', "media_type"='movie', "release_year"=2008, "poster_url"='https://image.tmdb.org/t/p/w500/8oRUTyP1QAtGDMvRpKZyuyFPG0U.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/h71xyiurUscD6uIPbECyso1Lwb9.jpg', "overview"='Jake, full of anger after his father''s death, is just starting to find a place for himself at his new Orlando high school - until Ryan, head of an underground MMA fight club, picks Jake out as a prime opponent. After being trounced by Ryan in front of the entire school, Jake begins training under the firm, moral guidance of a MMA master, where he learns how to fight... and how to avoid a fight. But it becomes obvious that a rematch will be inevitable if Jake wants to stop Ryan and his bullying, once and for all.', "external_url"=NULL, "platforms"=NULL, "popularity"=7.3616, "vote_average"=6.782, "is_ambiguous"=0, "evidence_score"=6.43, "created_at"='2026-08-03 14:31:56', "updated_at"='2026-08-19 01:49:52' WHERE "id"=6707;
