UPDATE "recommendations" SET "tmdb_id"=165220, "imdb_id"='tt0167285', "igdb_id"=NULL, "title"='The Mind''s Eye', "original_title"='The Mind''s Eye', "media_type"='movie', "release_year"=1990, "poster_url"='https://image.tmdb.org/t/p/w500/8owGK5kSi9Hodybs3fQjRMZq0ht.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/ms4y2vhF3uNLB3sWMvQ6NsAkFBf.jpg', "overview"='The Mind''s Eye is a compilation of experimental computer animations from when such technology was in its early infancy. The animations are from various studios, having been arranged in a sort of "2001" evolution-timeline theme, and set to synthesized music. These pioneering CGI projects later gave rise to films such as Toy Story, A Bug''s Life, Antz, and Shrek.', "external_url"=NULL, "platforms"=NULL, "popularity"=0.5546, "vote_average"=7.5, "is_ambiguous"=0, "evidence_score"=2.015, "created_at"='2026-08-03 14:31:56', "updated_at"='2026-08-19 01:49:52' WHERE "id"=6876;
