UPDATE "recommendations" SET "tmdb_id"=954513, "imdb_id"=NULL, "igdb_id"=NULL, "title"='Henze: Ondine', "original_title"='Henze: Ondine', "media_type"='movie', "release_year"=2009, "poster_url"='https://image.tmdb.org/t/p/w500/c32YkbTraK64DNOKTxEGjjBSnHO.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/44N3wbX76lxAaQbpuO1pnCJkWWa.jpg', "overview"='‘Ondine’, a ballet by Frederick Ashton, premiered at the Royal Opera House, Covent Garden, on 27 October 1958, with Margot Fonteyn in the title role of the water nymph. In this 2009 revival (27 May 2009 to 8 June 2009) at the Royal Opera House, Covent Garden, in London, the role of Ondine is performed by Miyako Yoshida, in the spellbinding underwater world of Ondine, staged by the Royal Ballet. Frederick Ashton’s shimmering choreography, Lila de Nobili’s impressionistic sets and Hans Werner Henze’s vibrant and inventive score, composed especially for the occasion, combine in an unforgettable way to evoke the myriad moods and colours of the sea.', "external_url"=NULL, "platforms"=NULL, "popularity"=1.2619, "vote_average"=0.0, "is_ambiguous"=0, "evidence_score"=5.01500000000000056e+00, "created_at"='2026-08-04 03:20:13', "updated_at"='2026-08-19 01:49:52' WHERE "id"=7022;
