UPDATE "recommendations" SET "tmdb_id"=14285, "imdb_id"='tt0096257', "igdb_id"=NULL, "title"='The Thin Blue Line', "original_title"='The Thin Blue Line', "media_type"='movie', "release_year"=1988, "poster_url"='https://image.tmdb.org/t/p/w500/4w4BJk3l8y9gYwPPLRs6uPHOmGL.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/9ndhlUu1VQ44pX5dVFo5Y19KqAl.jpg', "overview"='An unorthodox investigation into the wrongful conviction of Randall Dale Adams for the 1976 murder of Dallas police officer Robert Wood. Using stylized reenactments and interviews with key figures, conflicting testimonies and evidence are presented to argue that Adams was framed by a corrupt justice system, ultimately leading to his exoneration.', "external_url"=NULL, "platforms"=NULL, "popularity"=2.6681, "vote_average"=7.652, "is_ambiguous"=0, "evidence_score"=5.275, "created_at"='2026-08-11 22:09:33', "updated_at"='2026-08-19 01:49:52' WHERE "id"=9439;
