UPDATE "recommendations" SET "tmdb_id"=NULL, "imdb_id"=NULL, "igdb_id"=59, "title"='The Elder Scrolls IV: Oblivion', "original_title"='The Elder Scrolls IV: Oblivion', "media_type"='game', "release_year"=2006, "poster_url"='https://images.igdb.com/igdb/image/upload/t_cover_big/co8fpz.jpg', "backdrop_url"=NULL, "overview"='The Elder Scrolls IV: Oblivion, the fourth game in the Elder Scrolls story, is set within the province of Cyrodiil, the heartland and Imperial capital of Tamriel. Emperor Uriel Septim VII is assassinated in flight from his own palace, but just before he dies he passes on to you the mystic Amulet of Kings. The adventure proper begins with the quest to find Uriel''s lost and illegitimate son who is the only heir to the throne. In a world where the forces of darkness seek their ultimate dominion over the ranks of man and mer alike, you alone stand between the future of Tamriel and the gates of Oblivion.', "external_url"='https://www.igdb.com/games/the-elder-scrolls-iv-oblivion', "platforms"='["PlayStation 3", "PC (Microsoft Windows)", "Xbox 360"]', "popularity"=NULL, "vote_average"=NULL, "is_ambiguous"=0, "evidence_score"=5.26, "created_at"='2026-08-11 22:09:33', "updated_at"='2026-08-19 01:49:52' WHERE "id"=9479;
