UPDATE "recommendations" SET "tmdb_id"=197796, "imdb_id"='tt2316801', "igdb_id"=NULL, "title"='Beauty and the Beast', "original_title"='La Belle et la Bête', "media_type"='movie', "release_year"=2014, "poster_url"='https://image.tmdb.org/t/p/w500/8bErT2koHXAUSW5PdLQqgL5gEEe.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/92Uceuy7HaiiHFgW48gNyxhx17d.jpg', "overview"='Forced to face the cruel side of life, a devastated, bankrupt merchant chances upon the enchanted castle of a hideous creature, the mere sight of it chills the bone to the marrow. There, a fate worse than death awaits the poor father-of-six, who, after plucking a sweet-scented rose from the repulsive master''s verdant garden, must do the impossible: permit his compassionate daughter, Belle, to take his place and pay for the sins of her parent. Now, an impenetrable mystery shrouds the haunted mansion, and, as repugnance gradually turns into affection, only true love could break the spell.', "external_url"=NULL, "platforms"=NULL, "popularity"=6.8848, "vote_average"=6.29, "is_ambiguous"=0, "evidence_score"=6.545, "created_at"='2026-08-11 22:09:33', "updated_at"='2026-08-19 01:49:52' WHERE "id"=9516;
