UPDATE "recommendations" SET "tmdb_id"=94329, "imdb_id"='tt1899353', "igdb_id"=NULL, "title"='The Raid', "original_title"='Serbuan Maut', "media_type"='movie', "release_year"=2012, "poster_url"='https://image.tmdb.org/t/p/w500/Abnm1Ws3JH0ReCfEhLMPwPcMcGO.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/3wf5wV222vqTmz10y1vbrPgrGDf.jpg', "overview"='Deep in the heart of Jakarta''s slums lies an impenetrable safe house for the world''s most dangerous killers and gangsters. Until now, the run-down apartment block has been considered untouchable to even the bravest of police. Cloaked under the cover of pre-dawn darkness and silence, an elite swat team is tasked with raiding the safe house in order to take down the notorious drug lord that runs it.  But when a chance encounter with a spotter blows their cover and news of their assault reaches the drug lord, the building''s lights are cut and all the exits blocked. Stranded on the sixth floor with no way out, the unit must fight their way through the city''s worst to survive their mission. Starring Indonesian martial arts sensation Iko Uwais.', "external_url"=NULL, "platforms"=NULL, "popularity"=6.7522, "vote_average"=7.41, "is_ambiguous"=0, "evidence_score"=3.70333333333333314e+00, "created_at"='2026-08-11 22:09:33', "updated_at"='2026-08-19 01:49:52' WHERE "id"=9635;
